with exploded as (select id, created_at, attr_key, value from carts lateral view outer explode(attributes) t as attr_key, value) select date_trunc('hour', created_at) as hour_window, attr_key, count(*) as row_count, size(collect_set(attr_key)) as num_attr_keys, min(created_at) as first_seen, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as span_minutes, count(distinct id) as distinct_ids, max(created_at) as ended_at, rank() over (partition by date_trunc('hour', created_at) order by (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 desc) as span_minutes_rank from exploded group by hour_window, attr_key having size(collect_set(attr_key)) > 1 order by distinct_ids desc nulls first
